145	/// SPS serialization for integral types, bool, and char.
146	template <typename SPSTagT>
147	class SPSSerializationTraits<
148	    SPSTagT, SPSTagT,
149	    std::enable_if_t<std::is_same<SPSTagT, bool>::value ||
150	                     std::is_same<SPSTagT, char>::value ||
151	                     std::is_same<SPSTagT, int8_t>::value ||
152	                     std::is_same<SPSTagT, int16_t>::value ||
153	                     std::is_same<SPSTagT, int32_t>::value ||
154	                     std::is_same<SPSTagT, int64_t>::value ||
155	                     std::is_same<SPSTagT, uint8_t>::value ||
156	                     std::is_same<SPSTagT, uint16_t>::value ||
157	                     std::is_same<SPSTagT, uint32_t>::value ||
158	                     std::is_same<SPSTagT, uint64_t>::value>> {
159	public:
160	  static size_t size(const SPSTagT &Value) { return sizeof(SPSTagT); }
161	
162	  static bool serialize(SPSOutputBuffer &OB, const SPSTagT &Value) {
163	    SPSTagT Tmp = (endian::native == endian::big) ? byteswap(Value) : Value;
164	    return OB.write(reinterpret_cast<const char *>(&Tmp), sizeof(Tmp));
165	  }
166	
167	  static bool deserialize(SPSInputBuffer &IB, SPSTagT &Value) {
168	    SPSTagT Tmp;
169	    if (!IB.read(reinterpret_cast<char *>(&Tmp), sizeof(Tmp)))
170	      return false;
171	    Value = (endian::native == endian::big) ? byteswap(Tmp) : Tmp;
172	    return true;
173	  }
174	};
