176	class SPSSize;
177	
178	/// SPSSize is serializable to/from size_t. Wire size is 64-bits.
179	template <> class SPSSerializationTraits<SPSSize, size_t> {
180	public:
181	  static size_t size(const size_t &Value) {
182	    return SPSArgList<uint64_t>::size(static_cast<uint64_t>(Value));
183	  }
184	  static bool serialize(SPSOutputBuffer &OB, const size_t &Value) {
185	    return SPSArgList<uint64_t>::serialize(OB, static_cast<uint64_t>(Value));
186	  }
187	  static bool deserialize(SPSInputBuffer &IB, size_t &Value) {
188	    uint64_t Tmp;
189	    if (!SPSArgList<uint64_t>::deserialize(IB, Tmp))
190	      return false;
191	    if (Tmp > std::numeric_limits<size_t>::max())
192	      return false;
193	    Value = Tmp;
194	    return true;
195	  }
196	};
