201	/// SPS tag type for tuples.
202	///
203	/// A blob tuple should be serialized by serializing each of the elements in
204	/// sequence.
205	template <typename... SPSTagTs> class SPSTuple {
206	public:
207	  /// Convenience typedef of the corresponding arg list.
208	  typedef SPSArgList<SPSTagTs...> AsArgList;
209	};
