211	/// SPS tag type for optionals.
212	///
213	/// SPSOptionals should be serialized as a bool with true indicating that an
214	/// SPSTagT value is present, and false indicating that there is no value.
215	/// If the boolean is true then the serialized SPSTagT will follow immediately
216	/// after it.
217	template <typename SPSTagT> class SPSOptional;
