219	/// SPS tag type for sequences.
220	///
221	/// SPSSequences should be serialized as a uint64_t sequence length,
222	/// followed by the serialization of each of the elements.
223	template <typename SPSElementTagT> class SPSSequence;
224	
225	/// SPS tag type for strings, which are equivalent to sequences of chars.
226	using SPSString = SPSSequence<char>;
227	
228	/// SPS tag type for maps.
229	///
230	/// SPS maps are just sequences of (Key, Value) tuples.
231	template <typename SPSTagT1, typename SPSTagT2>
232	using SPSMap = SPSSequence<SPSTuple<SPSTagT1, SPSTagT2>>;
