236	public:
237	  static size_t size(const SPSEmpty &EP) { return 0; }
238	  static bool serialize(SPSOutputBuffer &OB, const SPSEmpty &BE) {
239	    return true;
240	  }
241	  static bool deserialize(SPSInputBuffer &IB, SPSEmpty &BE) { return true; }
