244	/// Specialize this to implement 'trivial' sequence serialization for
245	/// a concrete sequence type.
246	///
247	/// Trivial sequence serialization uses the sequence's 'size' member to get the
248	/// length of the sequence, and uses a range-based for loop to iterate over the
249	/// elements.
250	///
251	/// Specializing this template class means that you do not need to provide a
252	/// specialization of SPSSerializationTraits for your type.
253	template <typename SPSElementTagT, typename ConcreteSequenceT>
254	class TrivialSPSSequenceSerialization {
255	public:
256	  static constexpr bool available = false;
257	};
258	
259	/// Specialize this to implement 'trivial' sequence deserialization for
260	/// a concrete sequence type.
261	///
262	/// Trivial deserialization calls a static 'reserve(SequenceT&)' method on your
263	/// specialization (you must implement this) to reserve space, and then calls
264	/// a static 'append(SequenceT&, ElementT&) method to append each of the
265	/// deserialized elements.
266	///
267	/// Specializing this template class means that you do not need to provide a
268	/// specialization of SPSSerializationTraits for your type.
269	template <typename SPSElementTagT, typename ConcreteSequenceT>
270	class TrivialSPSSequenceDeserialization {
271	public:
272	  static constexpr bool available = false;
273	};
