275	/// Trivial std::string -> SPSSequence<char> serialization.
276	template <> class TrivialSPSSequenceSerialization<char, std::string> {
277	public:
278	  static constexpr bool available = true;
279	};
280	
281	/// Trivial SPSSequence<char> -> std::string deserialization.
282	template <> class TrivialSPSSequenceDeserialization<char, std::string> {
283	public:
284	  static constexpr bool available = true;
285	
286	  using element_type = char;
287	
288	  static void reserve(std::string &S, uint64_t Size) { S.reserve(Size); }
289	  static bool append(std::string &S, char C) {
290	    S.push_back(C);
291	    return true;
292	  }
293	};
