302	/// Trivial span<T> -> SPSSequence<SPSElementTagT> serialization.
303	template <typename SPSElementTagT, typename T>
304	class TrivialSPSSequenceSerialization<SPSElementTagT, span<T>> {
305	public:
306	  static constexpr bool available = true;
307	};
