309	/// Trivial SPSSequence<SPSElementTagT> -> std::vector<T> deserialization.
310	template <typename SPSElementTagT, typename T>
311	class TrivialSPSSequenceDeserialization<SPSElementTagT, std::vector<T>> {
312	public:
313	  static constexpr bool available = true;
314	
315	  using element_type = typename std::vector<T>::value_type;
316	
317	  static void reserve(std::vector<T> &V, uint64_t Size) { V.reserve(Size); }
318	  static bool append(std::vector<T> &V, T E) {
319	    V.push_back(std::move(E));
320	    return true;
321	  }
322	};
