324	/// Trivial std::unordered_map<K, V> -> SPSSequence<SPSTuple<SPSKey, SPSValue>>
325	/// serialization.
326	template <typename SPSKeyTagT, typename SPSValueTagT, typename K, typename V>
327	class TrivialSPSSequenceSerialization<SPSTuple<SPSKeyTagT, SPSValueTagT>,
328	                                      std::unordered_map<K, V>> {
329	public:
330	  static constexpr bool available = true;
331	};
332	
333	/// Trivial SPSSequence<SPSTuple<SPSKey, SPSValue>> -> std::unordered_map<K, V>
334	/// deserialization.
335	template <typename SPSKeyTagT, typename SPSValueTagT, typename K, typename V>
336	class TrivialSPSSequenceDeserialization<SPSTuple<SPSKeyTagT, SPSValueTagT>,
337	                                        std::unordered_map<K, V>> {
338	public:
339	  static constexpr bool available = true;
340	
341	  using element_type = std::pair<K, V>;
342	
343	  static void reserve(std::unordered_map<K, V> &M, uint64_t Size) {
344	    M.reserve(Size);
345	  }
346	  static bool append(std::unordered_map<K, V> &M, element_type E) {
347	    return M.insert(std::move(E)).second;
348	  }
349	};
