351	/// 'Trivial' sequence serialization: Sequence is serialized as a uint64_t size
352	/// followed by a for-earch loop over the elements of the sequence to serialize
353	/// each of them.
354	template <typename SPSElementTagT, typename SequenceT>
355	class SPSSerializationTraits<SPSSequence<SPSElementTagT>, SequenceT,
356	                             std::enable_if_t<TrivialSPSSequenceSerialization<
357	                                 SPSElementTagT, SequenceT>::available>> {
358	public:
359	  static size_t size(const SequenceT &S) {
360	    size_t Size = SPSArgList<uint64_t>::size(static_cast<uint64_t>(S.size()));
361	    for (const auto &E : S)
362	      Size += SPSArgList<SPSElementTagT>::size(E);
363	    return Size;
364	  }
365	
366	  static bool serialize(SPSOutputBuffer &OB, const SequenceT &S) {
367	    if (!SPSArgList<uint64_t>::serialize(OB, static_cast<uint64_t>(S.size())))
368	      return false;
369	    for (const auto &E : S)
370	      if (!SPSArgList<SPSElementTagT>::serialize(OB, E))
371	        return false;
372	    return true;
373	  }
374	
375	  static bool deserialize(SPSInputBuffer &IB, SequenceT &S) {
376	    using TBSD = TrivialSPSSequenceDeserialization<SPSElementTagT, SequenceT>;
377	    uint64_t Size;
378	    if (!SPSArgList<uint64_t>::deserialize(IB, Size))
379	      return false;
380	    TBSD::reserve(S, Size);
381	    for (size_t I = 0; I != Size; ++I) {
382	      typename TBSD::element_type E;
383	      if (!SPSArgList<SPSElementTagT>::deserialize(IB, E))
384	        return false;
385	      if (!TBSD::append(S, std::move(E)))
386	        return false;
387	    }
388	    return true;
389	  }
390	};
