392	/// Serialization (but no deserialization) from iterator range.
393	template <typename SPSElementTagT, typename IteratorT>
394	class SPSSerializationTraits<SPSSequence<SPSElementTagT>,
395	                             iterator_range<IteratorT>> {
396	  static uint64_t rangeSize(const iterator_range<IteratorT> &R) {
397	    return std::distance(R.begin(), R.end());
398	  }
399	
400	public:
401	  static size_t size(const iterator_range<IteratorT> &R) {
402	    size_t Size = SPSArgList<uint64_t>::size(rangeSize(R));
403	    for (const auto &E : R)
404	      Size += SPSArgList<SPSElementTagT>::size(E);
405	    return Size;
406	  }
407	
408	  static bool serialize(SPSOutputBuffer &OB,
409	                        const iterator_range<IteratorT> &R) {
410	    if (!SPSArgList<uint64_t>::serialize(OB, rangeSize(R)))
411	      return false;
412	    for (const auto &E : R)
413	      if (!SPSArgList<SPSElementTagT>::serialize(OB, E))
414	        return false;
415	    return true;
416	  }
417	};
