419	/// Trivial serialization / deserialization for span<char>
420	template <> class SPSSerializationTraits<SPSSequence<char>, span<const char>> {
421	public:
422	  static size_t size(const span<const char> &S) {
423	    return SPSArgList<uint64_t>::size(static_cast<uint64_t>(S.size())) +
424	           S.size();
425	  }
426	  static bool serialize(SPSOutputBuffer &OB, const span<const char> &S) {
427	    if (!SPSArgList<uint64_t>::serialize(OB, static_cast<uint64_t>(S.size())))
428	      return false;
429	    return OB.write(S.data(), S.size());
430	  }
431	  static bool deserialize(SPSInputBuffer &IB, span<const char> &S) {
432	    uint64_t Size;
433	    if (!SPSArgList<uint64_t>::deserialize(IB, Size))
434	      return false;
435	    S = span<const char>(IB.data(), Size);
436	    return IB.skip(Size);
437	  }
438	};
