440	/// SPSTuple serialization for std::tuple.
441	template <typename... SPSTagTs, typename... Ts>
442	class SPSSerializationTraits<SPSTuple<SPSTagTs...>, std::tuple<Ts...>> {
443	private:
444	  using TupleArgList = typename SPSTuple<SPSTagTs...>::AsArgList;
445	  using ArgIndices = std::make_index_sequence<sizeof...(Ts)>;
446	
447	  template <std::size_t... I>
448	  static size_t size(const std::tuple<Ts...> &T, std::index_sequence<I...>) {
449	    return TupleArgList::size(std::get<I>(T)...);
450	  }
451	
452	  template <std::size_t... I>
453	  static bool serialize(SPSOutputBuffer &OB, const std::tuple<Ts...> &T,
454	                        std::index_sequence<I...>) {
455	    return TupleArgList::serialize(OB, std::get<I>(T)...);
456	  }
457	
458	  template <std::size_t... I>
459	  static bool deserialize(SPSInputBuffer &IB, std::tuple<Ts...> &T,
460	                          std::index_sequence<I...>) {
461	    return TupleArgList::deserialize(IB, std::get<I>(T)...);
462	  }
463	
464	public:
465	  static size_t size(const std::tuple<Ts...> &T) {
466	    return size(T, ArgIndices{});
467	  }
468	
469	  static bool serialize(SPSOutputBuffer &OB, const std::tuple<Ts...> &T) {
470	    return serialize(OB, T, ArgIndices{});
471	  }
472	
473	  static bool deserialize(SPSInputBuffer &IB, std::tuple<Ts...> &T) {
474	    return deserialize(IB, T, ArgIndices{});
475	  }
476	};
