478	/// SPSTuple serialization for std::pair.
479	template <typename SPSTagT1, typename SPSTagT2, typename T1, typename T2>
480	class SPSSerializationTraits<SPSTuple<SPSTagT1, SPSTagT2>, std::pair<T1, T2>> {
481	public:
482	  static size_t size(const std::pair<T1, T2> &P) {
483	    return SPSArgList<SPSTagT1>::size(P.first) +
484	           SPSArgList<SPSTagT2>::size(P.second);
485	  }
486	
487	  static bool serialize(SPSOutputBuffer &OB, const std::pair<T1, T2> &P) {
488	    return SPSArgList<SPSTagT1>::serialize(OB, P.first) &&
489	           SPSArgList<SPSTagT2>::serialize(OB, P.second);
490	  }
491	
492	  static bool deserialize(SPSInputBuffer &IB, std::pair<T1, T2> &P) {
493	    return SPSArgList<SPSTagT1>::deserialize(IB, P.first) &&
494	           SPSArgList<SPSTagT2>::deserialize(IB, P.second);
495	  }
496	};
