498	/// SPSOptional serialization for std::optional.
499	template <typename SPSTagT, typename T>
500	class SPSSerializationTraits<SPSOptional<SPSTagT>, std::optional<T>> {
501	public:
502	  static size_t size(const std::optional<T> &Value) {
503	    size_t Size = SPSArgList<bool>::size(!!Value);
504	    if (Value)
505	      Size += SPSArgList<SPSTagT>::size(*Value);
506	    return Size;
507	  }
508	
509	  static bool serialize(SPSOutputBuffer &OB, const std::optional<T> &Value) {
510	    if (!SPSArgList<bool>::serialize(OB, !!Value))
511	      return false;
512	    if (Value)
513	      return SPSArgList<SPSTagT>::serialize(OB, *Value);
514	    return true;
515	  }
516	
517	  static bool deserialize(SPSInputBuffer &IB, std::optional<T> &Value) {
518	    bool HasValue;
519	    if (!SPSArgList<bool>::deserialize(IB, HasValue))
520	      return false;
521	    if (HasValue) {
522	      Value = T();
523	      return SPSArgList<SPSTagT>::deserialize(IB, *Value);
524	    } else
525	      Value = std::optional<T>();
526	    return true;
527	  }
528	};
