530	/// Serialization for string_views.
531	///
532	/// Serialization is as for regular strings. Deserialization points directly
533	/// into the blob.
534	template <> class SPSSerializationTraits<SPSString, std::string_view> {
535	public:
536	  static size_t size(const std::string_view &S) {
537	    return SPSArgList<uint64_t>::size(static_cast<uint64_t>(S.size())) +
538	           S.size();
539	  }
540	
541	  static bool serialize(SPSOutputBuffer &OB, const std::string_view &S) {
542	    if (!SPSArgList<uint64_t>::serialize(OB, static_cast<uint64_t>(S.size())))
543	      return false;
544	    return OB.write(S.data(), S.size());
545	  }
546	
547	  static bool deserialize(SPSInputBuffer &IB, std::string_view &S) {
548	    const char *Data = nullptr;
549	    uint64_t Size;
550	    if (!SPSArgList<uint64_t>::deserialize(IB, Size))
551	      return false;
552	    if (Size > std::numeric_limits<size_t>::max())
553	      return false;
554	    Data = IB.data();
555	    if (!IB.skip(Size))
556	      return false;
557	    S = {Data, static_cast<size_t>(Size)};
558	    return true;
559	  }
560	};
