590	
591	  static bool serialize(SPSOutputBuffer &OB, T *const &P) {
592	    return SPSArgList<SPSExecutorAddr>::serialize(OB, ExecutorAddr::fromPtr(P));
593	  }
594	
595	  static bool deserialize(SPSInputBuffer &IB, T *&P) {
596	    ExecutorAddr Value;
597	    if (!SPSArgList<SPSExecutorAddr>::deserialize(IB, Value))
598	      return false;
599	    P = Value.toPtr<T *>();
600	    return true;
601	  }
602	};
603	
604	class SPSExecutorAddrRange;
605	
606	template <>
607	class SPSSerializationTraits<SPSExecutorAddrRange, ExecutorAddrRange> {
608	public:
609	  static size_t size(const ExecutorAddrRange &R) {
610	    return SPSArgList<SPSExecutorAddr, SPSExecutorAddr>::size(R.Start, R.End);
611	  }
612	
613	  static bool serialize(SPSOutputBuffer &OB, const ExecutorAddrRange &R) {
614	    return SPSArgList<SPSExecutorAddr, SPSExecutorAddr>::serialize(OB, R.Start,
615	                                                                   R.End);
616	  }
617	
618	  static bool deserialize(SPSInputBuffer &IB, ExecutorAddrRange &R) {
619	    return SPSArgList<SPSExecutorAddr, SPSExecutorAddr>::deserialize(
620	        IB, R.Start, R.End);
621	  }
622	};
623	
624	/// SPS tag type for errors.
625	class SPSError;
626	
627	/// Helper type for serializing Errors.
628	///
629	/// llvm::Errors are move-only, and not inspectable except by consuming them.
630	/// This makes them unsuitable for direct serialization via
631	/// SPSSerializationTraits, which needs to inspect values twice (once to
632	/// determine the amount of space to reserve, and then again to serialize).
633	///
634	/// The SPSSerializableError type is a helper that can be
635	/// constructed from an llvm::Error, but inspected more than once.
636	struct SPSSerializableError {
637	  SPSSerializableError() = default;
638	  SPSSerializableError(Error Err) {
639	    if (Err)
640	      Msg = toString(std::move(Err));
641	  }
642	
643	  Error toError() {
644	    if (Msg)
645	      return make_error<StringError>(std::move(*Msg));
646	    return Error::success();
647	  }
648	
649	  std::optional<std::string> Msg;
650	};
651	
652	template <> class SPSSerializationTraits<SPSError, SPSSerializableError> {
653	public:
654	  static size_t size(const SPSSerializableError &E) {
655	    if (E.Msg)
656	      return SPSArgList<bool, SPSString>::size(true, *E.Msg);
657	    else
658	      return SPSArgList<bool>::size(false);
659	  }
660	
661	  static bool serialize(SPSOutputBuffer &OB, const SPSSerializableError &E) {
662	    if (E.Msg)
663	      return SPSArgList<bool, SPSString>::serialize(OB, true, *E.Msg);
664	    else
665	      return SPSArgList<bool>::serialize(OB, false);
666	  }
667	
668	  static bool deserialize(SPSInputBuffer &IB, SPSSerializableError &E) {
669	    bool HasError = false;
670	    if (!SPSArgList<bool>::deserialize(IB, HasError))
671	      return false;
672	    if (HasError) {
673	      std::string Msg;
674	      if (!SPSArgList<SPSString>::deserialize(IB, Msg))
675	        return false;
676	      E.Msg = std::move(Msg);
677	    } else
678	      E.Msg = std::nullopt;
679	    return true;
680	  }
681	};
682	
683	/// SPS tag type for expecteds, which are either a T or a string representing
684	/// an error.
685	template <typename SPSTagT> class SPSExpected;
686	
687	/// Helper type for serializing Expected<T>s.
688	///
689	/// See SPSSerializableError for more details.
690	template <typename T> struct SPSSerializableExpected {
691	  SPSSerializableExpected() = default;
692	  explicit SPSSerializableExpected(Expected<T> E) {
693	    if (E)
694	      Val = decltype(Val)(std::in_place_index<0>, std::move(*E));
695	    else
696	      Val = decltype(Val)(std::in_place_index<1>, toString(E.takeError()));
697	  }
698	
699	  Expected<T> toExpected() {
700	    if (Val.index() == 0)
701	      return Expected<T>(std::move(std::get<0>(Val)));
702	    return Expected<T>(make_error<StringError>(std::move(std::get<1>(Val))));
703	  }
704	
705	  std::variant<T, std::string> Val{std::in_place_index<0>, T()};
706	};
707	
708	template <typename T>
709	SPSSerializableExpected<T> toSPSSerializableExpected(Expected<T> E) {
710	  return SPSSerializableExpected<T>(std::move(E));
711	}
712	
713	template <typename T>
714	SPSSerializableExpected<T> toSPSSerializableExpected(T Val) {
715	  return SPSSerializableExpected<T>(std::move(Val));
716	}
717	
718	template <typename T>
719	SPSSerializableExpected<T> toSPSSerializableExpected(Error E) {
720	  return SPSSerializableExpected<T>(std::move(E));
721	}
722	
723	template <typename SPSTagT, typename T>
724	class SPSSerializationTraits<SPSExpected<SPSTagT>, SPSSerializableExpected<T>> {
725	public:
726	  static size_t size(const SPSSerializableExpected<T> &E) {
727	    if (E.Val.index() == 0)
728	      return SPSArgList<bool, SPSTagT>::size(true, std::get<0>(E.Val));
729	    else
730	      return SPSArgList<bool, SPSString>::size(false, std::get<1>(E.Val));
731	  }
732	
733	  static bool serialize(SPSOutputBuffer &OB,
734	                        const SPSSerializableExpected<T> &E) {
735	    if (E.Val.index() == 0)
736	      return SPSArgList<bool, SPSTagT>::serialize(OB, true, std::get<0>(E.Val));
737	    else
738	      return SPSArgList<bool, SPSString>::serialize(OB, false,
739	                                                    std::get<1>(E.Val));
740	  }
741	
742	  static bool deserialize(SPSInputBuffer &IB, SPSSerializableExpected<T> &E) {
743	    bool HasValue = false;
744	    if (!SPSArgList<bool>::deserialize(IB, HasValue))
745	      return false;
746	    if (HasValue) {
747	      T Val;
748	      if (!SPSArgList<SPSTagT>::deserialize(IB, Val))
749	        return false;
750	      E.Val = decltype(E.Val){std::in_place_index<0>, std::move(Val)};
751	    } else {
752	      std::string Msg;
753	      if (!SPSArgList<SPSString>::deserialize(IB, Msg))
754	        return false;
755	      E.Val = decltype(E.Val){std::in_place_index<1>, std::move(Msg)};
756	    }
757	    return true;
758	  }
759	};
760	
761	/// Serialize to a SPSExpected<SPSTagT> from a SPSSerializableError.
762	template <typename SPSTagT>
763	class SPSSerializationTraits<SPSExpected<SPSTagT>, SPSSerializableError> {
764	public:
765	  static size_t size(const SPSSerializableError &SE) {
766	    assert(SE.Msg && "Cannot serialize expected from a success value");
767	    return SPSArgList<bool, SPSString>::size(false, *SE.Msg);
768	  }
769	
770	  static bool serialize(SPSOutputBuffer &OB, const SPSSerializableError &SE) {
771	    assert(SE.Msg && "Cannot serialize expected from a success value");
772	    return SPSArgList<bool, SPSString>::serialize(OB, false, *SE.Msg);
773	  }
774	};
775	
776	/// Serialize to a SPSExpected<SPSTagT> from a T.
777	template <typename SPSTagT, typename T>
778	class SPSSerializationTraits<SPSExpected<SPSTagT>, T> {
779	public:
780	  static size_t size(const T &Value) {
781	    return SPSArgList<bool>::size(true) + SPSArgList<SPSTagT>::size(Value);
782	  }
783	
784	  static bool serialize(SPSOutputBuffer &OB, const T &Value) {
785	    return SPSArgList<bool, SPSTagT>::serialize(OB, true, Value);
786	  }
787	};
788	
789	} // namespace orc_rt
790	
791	#endif // ORC_RT_SIMPLEPACKEDSERIALIZATION_H
