1	//===-------- bit.h - Substitute for future STL bit APIs -------*- C++ -*-===//
2	//
3	// Part of the LLVM Project, under the Apache License v2.0 with LLVM Exceptions.
4	// See https://llvm.org/LICENSE.txt for license information.
5	// SPDX-License-Identifier: Apache-2.0 WITH LLVM-exception
6	//
7	//===----------------------------------------------------------------------===//
8	//
9	// Substitutes for STL <bit> APIs that aren't available to the ORC runtime yet.
10	//
11	// TODO: Replace all uses once the respective APIs are available.
12	//
13	//===----------------------------------------------------------------------===//
14	
15	#ifndef ORC_RT_BIT_H
16	#define ORC_RT_BIT_H
17	
18	#include <cstddef>
19	#include <cstdint>
20	#include <limits>
21	#include <type_traits>
22	#if defined(_MSC_VER) && !defined(_DEBUG)
23	#include <stdlib.h>
24	#endif
25	
26	#if defined(__linux__) || defined(__GNU__) || defined(__HAIKU__) ||            \
27	    defined(__Fuchsia__) || defined(__EMSCRIPTEN__)
28	#include <endian.h>
29	#elif defined(_AIX)
30	#include <sys/machine.h>
31	#elif defined(__sun)
32	/* Solaris provides _BIG_ENDIAN/_LITTLE_ENDIAN selector in sys/types.h */
33	#include <sys/types.h>
34	#define BIG_ENDIAN 4321
35	#define LITTLE_ENDIAN 1234
36	#if defined(_BIG_ENDIAN)
37	#define BYTE_ORDER BIG_ENDIAN
38	#else
39	#define BYTE_ORDER LITTLE_ENDIAN
40	#endif
41	#elif defined(__MVS__)
42	#define BIG_ENDIAN 4321
43	#define LITTLE_ENDIAN 1234
44	#define BYTE_ORDER BIG_ENDIAN
45	#else
46	#if !defined(BYTE_ORDER) && !defined(_WIN32)
47	#include <machine/endian.h>
48	#endif
49	#endif
50	
51	namespace orc_rt {
52	
53	enum class endian {
54	  big,
55	  little,
56	#if defined(BYTE_ORDER) && defined(BIG_ENDIAN) && BYTE_ORDER == BIG_ENDIAN
57	  native = big
58	#else
59	  native = little
60	#endif
61	};
62	
63	template <typename T, typename = std::enable_if_t<std::is_integral_v<T>>>
64	[[nodiscard]] constexpr T byteswap(T V) noexcept {
65	  // Implementation taken from llvm/include/ADT/bit.h.
66	  if constexpr (sizeof(T) == 1) {
67	    return V;
68	  } else if constexpr (sizeof(T) == 2) {
69	    uint16_t UV = V;
70	#if defined(_MSC_VER) && !defined(_DEBUG)
71	    // The DLL version of the runtime lacks these functions (bug!?), but in a
72	    // release build they're replaced with BSWAP instructions anyway.
73	    return _byteswap_ushort(UV);
74	#else
75	    uint16_t Hi = UV << 8;
76	    uint16_t Lo = UV >> 8;
77	    return Hi | Lo;
78	#endif
79	  } else if constexpr (sizeof(T) == 4) {
80	    uint32_t UV = V;
81	#if __has_builtin(__builtin_bswap32)
82	    return __builtin_bswap32(UV);
83	#elif defined(_MSC_VER) && !defined(_DEBUG)
84	    return _byteswap_ulong(UV);
85	#else
86	    uint32_t Byte0 = UV & 0x000000FF;
87	    uint32_t Byte1 = UV & 0x0000FF00;
88	    uint32_t Byte2 = UV & 0x00FF0000;
89	    uint32_t Byte3 = UV & 0xFF000000;
90	    return (Byte0 << 24) | (Byte1 << 8) | (Byte2 >> 8) | (Byte3 >> 24);
91	#endif
92	  } else if constexpr (sizeof(T) == 8) {
93	    uint64_t UV = V;
94	#if __has_builtin(__builtin_bswap64)
95	    return __builtin_bswap64(UV);
96	#elif defined(_MSC_VER) && !defined(_DEBUG)
97	    return _byteswap_uint64(UV);
98	#else
99	    uint64_t Hi = byteswap<uint32_t>(UV);
100	    uint32_t Lo = byteswap<uint32_t>(UV >> 32);
101	    return (Hi << 32) | Lo;
102	#endif
103	  } else {
104	    static_assert(!sizeof(T *), "Don't know how to handle the given type.");
105	    return 0;
106	  }
107	}
108	
109	/// Calculates the number of leading zeros.
110	template <typename T, typename _ = std::enable_if_t<std::is_unsigned_v<T>>>
111	[[nodiscard]] constexpr int countl_zero(T Val) noexcept {
112	  if (!Val)
113	    return std::numeric_limits<T>::digits;
114	
115	  unsigned ZeroBits = 0;
116	  for (T Shift = std::numeric_limits<T>::digits >> 1; Shift; Shift >>= 1) {
117	    T Tmp = Val >> Shift;
118	    if (Tmp)
119	      Val = Tmp;
120	    else
121	      ZeroBits |= Shift;
122	  }
123	  return ZeroBits;
124	}
125	
126	template <typename T, typename _ = std::enable_if_t<std::is_unsigned_v<T>>>
127	[[nodiscard]] constexpr int bit_width(T x) noexcept {
128	  return std::numeric_limits<T>::digits - countl_zero(x);
129	}
130	
131	template <typename T, typename = std::enable_if_t<std::is_unsigned_v<T>>>
132	[[nodiscard]] constexpr inline bool has_single_bit(T Value) noexcept {
133	  return (Value != 0) && ((Value & (Value - 1)) == 0);
134	}
135	
136	template <typename T, typename = std::enable_if_t<std::is_unsigned_v<T>>>
137	[[nodiscard]] constexpr T rotl(T V, int R) {
138	  constexpr unsigned N = std::numeric_limits<T>::digits;
139	
140	  static_assert(has_single_bit(N), "& (N - 1) is only valid for powers of two");
141	  R = R & (N - 1);
142	
143	  if (R == 0)
144	    return V;
145	
146	  return (V << R) | (V >> (N - R));
147	}
148	
149	template <typename T, typename = std::enable_if_t<std::is_unsigned_v<T>>>
150	[[nodiscard]] constexpr T rotr(T V, int R) {
151	  constexpr unsigned N = std::numeric_limits<T>::digits;
152	
153	  static_assert(has_single_bit(N), "& (N - 1) is only valid for powers of two");
154	  R = R & (N - 1);
155	
156	  if (R == 0)
157	    return V;
158	
159	  return (V >> R) | (V << (N - R));
160	}
161	
162	} // namespace orc_rt
163	
164	#endif // ORC_RT_BIT_H
